//! Merkle Tree Certificate fixtures generated by the draft PLANTS WG demo
//! (ietf-plants-wg/merkle-tree-certs, demo/mtc.json, "plants-07" wire version).
//! The CA has ID 32473.1; the standalone fixture is entry 10 of log 1 and the
//! landmark fixture is entry 32 of log 1. No signature verification is tested;
//! these assert decoding and retention only.

use x509_info::{parse_pem, ExtensionDetails, ParseOptions};

const STANDALONE: &[u8] = include_bytes!("fixtures/mtc-standalone.pem");
const LANDMARK: &[u8] = include_bytes!("fixtures/mtc-landmark.pem");
const CA: &[u8] = include_bytes!("fixtures/mtc-ca.pem");

#[test]
fn standalone_certificate_decodes_mtc_fields() {
    let info = parse_pem(STANDALONE, ParseOptions::default()).unwrap();
    // The demo output carries a trust-anchor-ids properties block.
    assert!(info.certificate_properties.is_some());
    let issuer_attribute = &info.issuer.rdns[0][0];
    assert_eq!(issuer_attribute.oid, "1.3.6.1.5.5.7.25.3");
    assert_eq!(issuer_attribute.label.as_deref(), Some("trustAnchorID"));
    assert_eq!(issuer_attribute.value.as_deref(), Some("32473.1"));
    assert_eq!(issuer_attribute.value_tag, 13);
    assert_eq!(info.signature_algorithm.oid, "1.3.6.1.5.5.7.6.67");
    assert_eq!(info.signature_algorithm.name.as_deref(), Some("MTC-Proof"));
    assert_eq!(
        info.tbs_signature_algorithm.oid,
        info.signature_algorithm.oid
    );
    let reference = info.mtc_entry_reference().unwrap();
    assert_eq!(reference.log_number, 1);
    assert_eq!(reference.entry_index, 10);
    let proof = info.mtc_proof().unwrap().unwrap();
    assert_eq!(proof.subtree_start, 8);
    assert_eq!(proof.subtree_end, 11);
    assert!(proof.entry_extensions.is_empty());
    assert_eq!(proof.inclusion_proof.len(), 32);
    // CA 32473.1 (ML-DSA-44) and cosigners 32473.2.1 (P-256) / 32473.2.2 (ML-DSA-65),
    // in the draft's canonical cosigner ID order.
    let ids: Vec<_> = proof
        .cosignatures
        .iter()
        .map(|c| c.cosigner_id.clone())
        .collect();
    assert_eq!(
        ids,
        [
            vec![0x81, 0xfd, 0x59, 0x01],
            vec![0x81, 0xfd, 0x59, 0x02, 0x01],
            vec![0x81, 0xfd, 0x59, 0x02, 0x02],
        ]
    );
    let sizes: Vec<usize> = proof
        .cosignatures
        .iter()
        .map(|c| c.signature.len())
        .collect();
    assert_eq!(sizes[0], 2420); // ML-DSA-44
    assert_eq!(sizes[2], 3309); // ML-DSA-65
}

#[test]
fn landmark_relative_certificate_has_no_cosignatures() {
    let info = parse_pem(LANDMARK, ParseOptions::default()).unwrap();
    let reference = info.mtc_entry_reference().unwrap();
    assert_eq!((reference.log_number, reference.entry_index), (1, 32));
    let proof = info.mtc_proof().unwrap().unwrap();
    assert_eq!(proof.inclusion_proof.len(), 32);
    assert!(proof.cosignatures.is_empty());
    assert!(proof.subtree_start <= reference.entry_index);
    assert!(reference.entry_index < proof.subtree_end);
}

#[test]
fn ca_certificate_decodes_mtc_extension_and_unsigned_algorithm() {
    let info = parse_pem(CA, ParseOptions::default()).unwrap();
    assert_eq!(info.signature_algorithm.oid, "1.3.6.1.5.5.7.6.36");
    assert_eq!(info.signature_algorithm.name.as_deref(), Some("unsigned"));
    assert_eq!(info.subject.rdns[0][0].value.as_deref(), Some("32473.1"));
    let extension = info
        .extensions
        .iter()
        .find(|e| e.oid == "1.3.6.1.5.5.7.1.38")
        .unwrap();
    assert!(extension.critical);
    let ExtensionDetails::MtcCertificationAuthority(authority) = &extension.details else {
        panic!("expected MTC CA details")
    };
    assert_eq!(authority.signature_algorithm_oid, "2.16.840.1.101.3.4.3.17");
    assert_eq!(
        authority.signature_algorithm_name.as_deref(),
        Some("ML-DSA-44")
    );
    assert_eq!(authority.min_serial, Some(1u64 << 48));
    assert_eq!(authority.max_serial, Some((5u64 << 48) | 0xffff_ffff_ffff));
}

#[test]
fn pem_block_rules_reject_duplicates_bundles_and_other_labels() {
    use x509_info::Error;
    let mut duplicate_properties = LANDMARK.to_vec();
    let block = &LANDMARK[..LANDMARK
        .windows(b"-----END CERTIFICATE PROPERTIES-----".len())
        .position(|w| w == b"-----END CERTIFICATE PROPERTIES-----")
        .map(|i| i + b"-----END CERTIFICATE PROPERTIES-----".len())
        .unwrap()];
    assert!(std::str::from_utf8(block).unwrap().contains("PROPERTIES"));
    duplicate_properties.extend_from_slice(block);
    assert_eq!(
        parse_pem(&duplicate_properties, ParseOptions::default()).unwrap_err(),
        Error::InvalidPem
    );
    let mut bundle = LANDMARK.to_vec();
    bundle.extend_from_slice(LANDMARK);
    assert_eq!(
        parse_pem(&bundle, ParseOptions::default()).unwrap_err(),
        Error::InvalidPem
    );
    let other = b"-----BEGIN X-----\nAA==\n-----END X-----\n";
    assert_eq!(
        parse_pem(other, ParseOptions::default()).unwrap_err(),
        Error::UnexpectedPemLabel
    );
    assert_eq!(
        parse_pem(b"", ParseOptions::default()).unwrap_err(),
        Error::InvalidPem
    );
}
